target.css:
:root {
  --ink: #20243a;
  --muted: #73788b;
  --paper: #fffdf8;
  --line: #e5e2da;
  --navy: #27345d;
  --gold: #f4c85f;
  --coral: #ef7863;
  --mint: #a9dcc7;
  --lilac: #e6e2f7;
}

.screening-card {
  box-sizing: border-box;
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  border-bottom: 1px solid var(--line);
}

.venue {
  display: flex;
  align-items: center;
  gap: 8px;
}

.mark {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  color: var(--navy);
  background: var(--gold);
  border-radius: 50%;
  font-size: 16px;
}

.venue-copy {
  margin: 0;
  color: var(--ink);
  font-size: 11px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: 0.08em;
}

.venue-copy span {
  color: var(--muted);
  font-size: 9px;
  letter-spacing: 0.12em;
}

.status {
  padding: 5px 8px;
  color: var(--navy);
  background: var(--mint);
  border-radius: 999px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.feature {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: 12px;
  padding: 12px 14px 10px;
}

.poster {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 104px;
  padding: 10px;
  color: var(--paper);
  background: var(--navy);
  border-radius: 12px;
}

.poster-code,
.poster-note {
  color: var(--gold);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.poster-title {
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.03em;
}

.details {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--coral);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.film-title {
  margin: 0;
  font-size: 21px;
  font-weight: 800;
  line-height: 1.1;
}

.meta {
  margin: 5px 0 8px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.2;
}

.chips {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.chip {
  padding: 3px 6px;
  color: var(--navy);
  background: var(--lilac);
  border-radius: 4px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.booking {
  display: grid;
  grid-template-columns: 112px 1fr;
  gap: 12px;
  padding: 10px 14px;
  border-top: 1px solid var(--line);
}

.seat-summary {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding-left: 10px;
  border-left: 3px solid var(--coral);
}

.seat-kicker,
.seat-note {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.seat-code {
  margin: 1px 0;
  color: var(--navy);
  font-size: 22px;
  line-height: 1;
}

.seat-note {
  font-weight: 600;
  letter-spacing: 0.02em;
}

.seat-map {
  display: flex;
  align-items: center;
  gap: 10px;
}

.screen-label {
  margin: 0;
  padding: 4px 5px;
  color: var(--muted);
  background: var(--line);
  border-radius: 3px;
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.09em;
  writing-mode: vertical-rl;
}

.seats {
  display: grid;
  grid-template-columns: repeat(4, 16px);
  gap: 5px;
}

.seat {
  display: block;
  width: 16px;
  height: 12px;
  background: var(--mint);
  border-radius: 4px 4px 2px 2px;
}

.seat.occupied {
  background: var(--line);
}

.seat.selected {
  background: var(--coral);
  outline: 2px solid var(--gold);
  outline-offset: 1px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  background: var(--lilac);
}

.price {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.price-label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.price-total {
  color: var(--navy);
  font-size: 18px;
}

.reserve-button {
  padding: 8px 11px;
  color: var(--paper);
  background: var(--navy);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 800;
}

.reserve-button span {
  margin-left: 5px;
  color: var(--gold);
  font-size: 15px;
}
